-- Permission vocabulary and system roles of the payroll module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the payroll permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('compensation_change:read'::text, 'compensation_change'::text, 'read'::text, 'Read compensation change'::text),
            ('payroll_entry:create'::text, 'payroll_entry'::text, 'create'::text, 'Create payroll entry'::text),
            ('payroll_entry:delete'::text, 'payroll_entry'::text, 'delete'::text, 'Delete payroll entry'::text),
            ('payroll_entry:purge'::text, 'payroll_entry'::text, 'purge'::text, 'Purge payroll entry'::text),
            ('payroll_entry:read'::text, 'payroll_entry'::text, 'read'::text, 'Read payroll entry'::text),
            ('payroll_entry:restore'::text, 'payroll_entry'::text, 'restore'::text, 'Restore payroll entry'::text),
            ('payroll_entry:update'::text, 'payroll_entry'::text, 'update'::text, 'Update payroll entry'::text),
