            ('salary_slip:create'::text, 'salary_slip'::text, 'create'::text, 'Create salary slip'::text),
            ('salary_slip:delete'::text, 'salary_slip'::text, 'delete'::text, 'Delete salary slip'::text),
            ('salary_slip:purge'::text, 'salary_slip'::text, 'purge'::text, 'Purge salary slip'::text),
            ('salary_slip:read'::text, 'salary_slip'::text, 'read'::text, 'Read salary slip'::text),
            ('salary_slip:restore'::text, 'salary_slip'::text, 'restore'::text, 'Restore salary slip'::text),
