            ('salary_slip_line:read'::text, 'salary_slip_line'::text, 'read'::text, 'Read salary slip line'::text),
            ('salary_slip_line:restore'::text, 'salary_slip_line'::text, 'restore'::text, 'Restore salary slip line'::text),
            ('salary_slip_line:update'::text, 'salary_slip_line'::text, 'update'::text, 'Update salary slip line'::text),
            ('salary_structure:create'::text, 'salary_structure'::text, 'create'::text, 'Create salary structure'::text),
            ('salary_structure:delete'::text, 'salary_structure'::text, 'delete'::text, 'Delete salary structure'::text),
            ('salary_structure:purge'::text, 'salary_structure'::text, 'purge'::text, 'Purge salary structure'::text),
            ('salary_structure:read'::text, 'salary_structure'::text, 'read'::text, 'Read salary structure'::text),
            ('salary_structure:restore'::text, 'salary_structure'::text, 'restore'::text, 'Restore salary structure'::text),
            ('salary_structure:update'::text, 'salary_structure'::text, 'update'::text, 'Update salary structure'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
